-- ============================================================================
-- Dự án — lớp bảo mật (ADR-0004, ADR-0008). Chặn bằng database:
--
--   1. Danh mục, quy trình mẫu: ai cũng đọc; chỉ tài khoản ở ĐƠN VỊ GỐC ghi.
--      Quy trình mẫu khóa (theo luật) thì không ai sửa.
--   2. Dự án, bước, thành viên: thấy khi đơn vị trong phạm vi HOẶC là thành viên.
--      Chỉ đơn vị trong phạm vi được ghi trực tiếp.
--   3. Thành viên ngoài đơn vị (nhà thầu, tư vấn) chỉ GỬI cập nhật qua một hàm
--      hẹp — không có lối nào để tự đánh dấu một bước là xong.
--   4. Không cấp DELETE. Trigger nhật ký và updated_at trên mọi bảng.
-- ============================================================================

-- ── Hàm ngữ cảnh ─────────────────────────────────────────────────────────────
-- SECURITY DEFINER: đọc bảng bị RLS che mà không đệ quy policy vào nhau.
CREATE FUNCTION app_o_don_vi_goc() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT EXISTS (
    SELECT 1 FROM tai_khoan t JOIN don_vi d ON d.id = t.don_vi_id
    WHERE t.id = app_tai_khoan_id() AND t.deleted_at IS NULL
      AND d.cha_id IS NULL AND d.deleted_at IS NULL
  )
$$;
--> statement-breakpoint
CREATE FUNCTION app_du_an_thanh_vien() RETURNS uuid[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT coalesce(array_agg(du_an_id), '{}') FROM du_an_thanh_vien
  WHERE tai_khoan_id = app_tai_khoan_id() AND deleted_at IS NULL
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_o_don_vi_goc() FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app_du_an_thanh_vien() FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_o_don_vi_goc() TO gdos_app;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_du_an_thanh_vien() TO gdos_app;
--> statement-breakpoint

-- ── Nhật ký: bản ghi dùng chung toàn hệ thống ghi vào đơn vị gốc ────────────
-- Danh mục, quy trình mẫu không thuộc đơn vị nào; không có dòng này thì RLS của
-- nhật ký che mất mọi thay đổi của chúng. Phần còn lại giữ nguyên như 0002.
CREATE OR REPLACE FUNCTION ghi_nhat_ky() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  cu   jsonb := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END;
  moi  jsonb := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END;
  dong jsonb := coalesce(moi, cu);
  hanh text  := TG_OP;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD IS NOT DISTINCT FROM NEW THEN
      RETURN NEW;
    END IF;
    IF cu ->> 'deleted_at' IS NULL AND moi ->> 'deleted_at' IS NOT NULL THEN
      hanh := 'XOA_MEM';
    ELSIF (cu ->> 'mat_khau_bam') IS DISTINCT FROM (moi ->> 'mat_khau_bam') THEN
      hanh := 'DOI_MAT_KHAU';
    END IF;
  END IF;

  INSERT INTO nhat_ky_thao_tac (tai_khoan_id, don_vi_id, hanh_dong, bang, ban_ghi_id, gia_tri_cu, gia_tri_moi)
  VALUES (
    app_tai_khoan_id(),
    coalesce(
      (dong ->> 'don_vi_id')::uuid,
      CASE WHEN TG_TABLE_NAME = 'don_vi' THEN (dong ->> 'id')::uuid END,
      CASE WHEN TG_TABLE_NAME IN ('danh_muc_gia_tri', 'quy_trinh_mau') THEN (SELECT id FROM don_vi_goc()) END
    ),
    hanh,
    TG_TABLE_NAME,
    coalesce(dong ->> 'id', dong ->> 'khoa'),
    cu - 'mat_khau_bam' - 'token_bam',
    moi - 'mat_khau_bam' - 'token_bam'
  );
  RETURN coalesce(NEW, OLD);
END
$$;
--> statement-breakpoint

