CREATE POLICY doc_chung ON danh_muc_gia_tri FOR SELECT USING (true);
--> statement-breakpoint
CREATE POLICY them_o_goc ON danh_muc_gia_tri FOR INSERT WITH CHECK (app_o_don_vi_goc());
--> statement-breakpoint
CREATE POLICY sua_o_goc ON danh_muc_gia_tri FOR UPDATE USING (app_o_don_vi_goc()) WITH CHECK (app_o_don_vi_goc());
--> statement-breakpoint
ALTER TABLE quy_trinh_mau ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
