--> statement-breakpoint
CREATE POLICY them_o_goc ON quy_trinh_mau FOR INSERT WITH CHECK (app_o_don_vi_goc() AND NOT khoa);
--> statement-breakpoint
CREATE POLICY sua_o_goc ON quy_trinh_mau FOR UPDATE
  USING (app_o_don_vi_goc() AND NOT khoa) WITH CHECK (app_o_don_vi_goc() AND NOT khoa);
