-- ── don_vi_id của bước và thành viên luôn bằng của dự án ────────────────────
-- Người gọi không tự khai được: lấy từ dự án. Dự án đổi chủ đầu tư thì bước và
-- thành viên đổi theo — RLS luôn lọc đúng.
CREATE FUNCTION dong_bo_don_vi_du_an() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  NEW.don_vi_id := (SELECT don_vi_id FROM du_an WHERE id = NEW.du_an_id);
  IF NEW.don_vi_id IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy dự án' USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER dong_bo_don_vi BEFORE INSERT OR UPDATE ON du_an_buoc FOR EACH ROW EXECUTE FUNCTION dong_bo_don_vi_du_an();
--> statement-breakpoint
CREATE TRIGGER dong_bo_don_vi BEFORE INSERT OR UPDATE ON du_an_thanh_vien FOR EACH ROW EXECUTE FUNCTION dong_bo_don_vi_du_an();
--> statement-breakpoint
CREATE FUNCTION du_an_doi_don_vi() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
BEGIN
  UPDATE du_an_buoc SET don_vi_id = NEW.don_vi_id WHERE du_an_id = NEW.id;
  UPDATE du_an_thanh_vien SET don_vi_id = NEW.don_vi_id WHERE du_an_id = NEW.id;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE TRIGGER doi_don_vi AFTER UPDATE OF don_vi_id ON du_an FOR EACH ROW
  WHEN (OLD.don_vi_id IS DISTINCT FROM NEW.don_vi_id) EXECUTE FUNCTION du_an_doi_don_vi();
--> statement-breakpoint

-- ── Nhà thầu / tư vấn gửi cập nhật — lối DUY NHẤT cho thành viên ngoài đơn vị ─
CREATE FUNCTION buoc_gui_cap_nhat(p_buoc uuid, p_ngay date, p_ghi_chu text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  b du_an_buoc%ROWTYPE;
BEGIN
  SELECT * INTO b FROM du_an_buoc WHERE id = p_buoc AND deleted_at IS NULL;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM du_an_thanh_vien
    WHERE du_an_id = b.du_an_id AND tai_khoan_id = app_tai_khoan_id()
      AND vai_tro IN ('nha-thau', 'tu-van') AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Chỉ nhà thầu, tư vấn của dự án được gửi cập nhật' USING ERRCODE = '42501';
  END IF;
  IF b.la_nhom OR b.la_nhap OR b.bo_qua OR b.ngay_hoan_thanh IS NOT NULL THEN
    RAISE EXCEPTION 'Bước này không nhận cập nhật' USING ERRCODE = '22023';
  END IF;
  UPDATE du_an_buoc
  SET cho_xac_nhan = jsonb_build_object(
        'ngay', p_ngay, 'ghiChu', coalesce(p_ghi_chu, ''),
        'nguoiGui', app_tai_khoan_id(), 'luc', now())
  WHERE id = p_buoc;
END
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION buoc_gui_cap_nhat(uuid, date, text) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION buoc_gui_cap_nhat(uuid, date, text) TO gdos_app;
--> statement-breakpoint

